import '@servicenow/sdk/global'
import { ChoiceColumn, StringColumn, Table } from '@servicenow/sdk/core'
import { calculateFieldValue } from '../project/src/server/calculate'
import { calculateFieldValue2 } from '../project/src/server/calculate2'

export const sn_table_app_reptile_table = Table({
    name: 'sn_table_app_reptile_table',
    label: 'Reptile Table',
    schema: {
        reptiles: ChoiceColumn({
            functionDefinition: 'glidefunction:add()',
            dropdown: 'dropdown_without_none',
            choices: { lizard: { label: 'Lizard', sequence: 1, inactive: false, inactiveOnUpdate: true } },
        }),
    },
    actions: ['read'],
    attributes: {
        update_synch: false,
    },
    liveFeed: false,
    accessibleFrom: 'package_private',
    allowWebServiceAccess: true,
    allowNewFields: true,
})

export const sn_table_app_animal_table = Table({
    name: 'sn_table_app_animal_table',
    label: 'Animal Table',
    extends: 'name',

    schema: {
        farm: StringColumn({
            label: 'Farm',
            dropdown: 'none',
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `javascript:global.getNextObjNumberPadded();`,
            },
            attributes: {
                edge_encryption_enabled: true,
            },
        }),
        animals: StringColumn({
            dropdown: 'dropdown_without_none',
            choices: {
                dog: { label: 'dog', sequence: 0 },
                cat: { label: 'cat', sequence: 1 },
            },
            label: 'Animals',
        }),
        matching_animals: StringColumn({
            dropdown: 'dropdown_without_none',
            dependent: 'animals',
            choices: {
                dog: { label: 'dog', sequence: 1 },
                cat: { label: 'cat', sequence: 0 },
            },
            label: 'Matching animals',
        }),
        favorite_animal: StringColumn({
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: calculateFieldValue,
            },
            label: 'Favorite animal',
            attributes: {
                edge_encryption_enabled: true,
            },
        }),
        reptiles_only: StringColumn({
            dropdown: 'dropdown_without_none',
            dynamicValueDefinitions: {
                type: 'choices_from_other_table',
                field: 'reptiles',
                table: 'sn_table_app_reptile_table',
            },
            label: 'Reptiles only',
            attributes: {
                edge_encryption_enabled: true,
            },
        }),
    },

    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    extensible: true,

    display: 'animals',

    actions: ['read', 'update', 'delete', 'create'],

    accessibleFrom: 'public',

    autoNumber: {
        prefix: 'farm',
        number: 100,
        numberOfDigits: 9,
    },

    liveFeed: true,
    audit: true,
    readOnly: false,
    textIndex: true,

    attributes: {
        updateSynch: 'other',
        anything: 'anything',
    },

    index: [{ name: 'index', unique: true, element: 'favorite_animal' }],
})

export const sn_table_app_dynamic = Table({
    name: 'sn_table_app_dynamic',
    schema: {
        calculated: StringColumn({
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: calculateFieldValue2,
            },
        }),
        dynamic_default: StringColumn({
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: 'javascript:current.name',
            },
        }),
        choices_from_other_table: StringColumn({
            dynamicValueDefinitions: {
                type: 'choices_from_other_table',
                table: 'sn_table_app_reptile_table',
                field: 'lizard',
            },
        }),
        dependent_field: StringColumn({
            dependent: 'dynamic_default',
        }),
    },
})

export const sn_table_app_licensed = Table({
    name: 'sn_table_app_licensed',
    licensingConfig: {
        licenseModel: 'producer',
        ownerCondition: 'my_own_condition',
        licenseCondition: 'my_license_condition',
        isFulfillment: true,
        opDelete: true,
        opUpdate: false,
        opInsert: true,
    },
    schema: {
        foo: StringColumn({ label: 'Foobar' }),
    },
})
